/** Generado por scripts/etl-concertacion.mjs — no editar a mano. */
export type ConcertacionFuel = "GAS" | "DIESEL" | string;

export type ConcertacionDailyRow = {
  date: string;
  campo: string;
  tag: string;
  model: string;
  fuel: ConcertacionFuel;
  kwh: number;
  kwAvg: number;
  op: number;
  sb: number;
  mmtPrev: number;
  mmtCorr: number;
  ext: number;
  failures: number;
};

export type ConcertacionUnitAgg = {
  tag: string;
  campo: string;
  model: string;
  fuel: ConcertacionFuel;
  capInstKw: number;
  capEntKw: number;
  kwh: number;
  op: number;
  sb: number;
  mmtPrev: number;
  mmtCorr: number;
  ext: number;
  failures: number;
  days: number;
  calendarHours: number;
  unavailable: number;
  availabilityPct: number | null;
};

export type ConcertacionEvent = {
  date: string;
  tag: string;
  campo: string;
  fuel: ConcertacionFuel;
  ext: number;
  failures: number;
  op: number;
  sb: number;
  mmtPrev: number;
  mmtCorr: number;
  obs: string | null;
};

export type ConcertacionMonthPack = {
  monthKey: string;
  year: number;
  dayCount: number;
  totals: {
    kwh: number;
    op: number;
    sb: number;
    mmtPrev: number;
    mmtCorr: number;
    ext: number;
    failures: number;
    calendarHours: number;
    units: number;
    unavailable: number;
    availabilityPct: number | null;
  };
  units: ConcertacionUnitAgg[];
  daily: ConcertacionDailyRow[];
  events: ConcertacionEvent[];
};

export type ConcertacionPack = {
  sourceFile: string;
  extractedAt: string;
  notes: string;
  months: Record<string, ConcertacionMonthPack>;
  generation3m: { month: string; gasKwh: number; dieselKwh: number }[];
};

